<script setup lang="ts">
import {computed,ref,onMounted,onUnmounted} from 'vue'
import {Clock3,Flame,BookOpen,Award,ArrowLeft,Sparkles} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {ContractError,type Document} from '../domain/local-contract'
import {readingSummary,type ReadingEvent,type ReadingGoal} from '../reader/activity-contract'
const store=useLocal(),events=ref<Document<ReadingEvent>[]>([]),goal=ref(20),goalRevision=ref(0),busy=ref(false),loaded=ref(false),error=ref(''),saved=ref(false),conflict=ref(false),summary=computed(()=>readingSummary(events.value)),max=computed(()=>Math.max(60,...summary.value.week.map(day=>day.seconds)))
let disposed=false,ticket=0,intent:{id:string;minutes:number;revision:number}|null=null
const minutes=(seconds:number)=>Number((seconds/60).toFixed(1)).toLocaleString('zh-CN')
async function load(refreshGoal=false){const vault=store.vault;if(!vault)return;const epoch=++ticket;try{const [rows,target]=await Promise.all([vault.listPrefix<ReadingEvent>('reading-event:'),vault.read<ReadingGoal>('settings:reading-goal')]);if(disposed||epoch!==ticket||store.vault!==vault||!vault.unlocked)return;events.value=rows;if(!loaded.value||refreshGoal){goal.value=target?.value.minutes||20;goalRevision.value=target?.revision||0;if(refreshGoal){intent=null;conflict.value=false;saved.value=false}};if(!conflict.value&&!intent)error.value='';loaded.value=true}catch(e){if(!disposed&&epoch===ticket&&store.vault===vault)error.value=(e as Error).message}}
async function save(){const vault=store.vault;if(!vault||busy.value||conflict.value)return;busy.value=true;saved.value=false;error.value='';if(!intent||intent.minutes!==goal.value)intent={id:crypto.randomUUID(),minutes:goal.value,revision:goalRevision.value};const current=intent;try{await vault.commit(current.id,'settings','settings:reading-goal',current.revision,{assetType:'reading-goal',minutes:current.minutes});if(disposed||store.vault!==vault)return;intent=null;goalRevision.value=current.revision+1;saved.value=true;await load()}catch(e){if(!disposed&&store.vault===vault){error.value=(e as Error).message;conflict.value=e instanceof ContractError&&e.code==='REVISION_CONFLICT'}}finally{if(!disposed&&store.vault===vault)busy.value=false}}
function committed(event:Event){const d=(event as CustomEvent<{vaultId:string;ids:string[];kinds:string[]}>).detail;if(d.vaultId===store.vault?.id&&(d.ids.some(id=>id.startsWith('reading-event:')||id==='settings:reading-goal')||d.kinds.includes('story')))void load()}
onMounted(()=>{void load();window.addEventListener('reader-private-commit',committed)})
onUnmounted(()=>{disposed=true;ticket++;window.removeEventListener('reader-private-commit',committed)})
</script>
<template><section class="private-insights"><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">TIME BETWEEN PAGES</span><h1>阅读记录</h1></div><div class="final-page-actions"><RouterLink class="final-icon-button" to="/local/agent" aria-label="打开创作助手"><Sparkles :size="20"/></RouterLink><RouterLink class="final-icon-button" to="/local/library" aria-label="返回书架"><ArrowLeft :size="21"/></RouterLink></div></div><p v-if="error" class="final-error" role="alert">{{error}}<button v-if="conflict" @click="load(true)">载入当前目标</button><button v-else @click="load()">重新加载</button></p><p v-if="!loaded" role="status">正在整理记录…</p><template v-else><div class="insights-top"><article class="insights-today"><span><Clock3 :size="18"/>今天</span><p><strong>{{minutes(summary.todaySeconds)}}</strong>分钟</p><progress :value="Math.min(summary.todaySeconds,goal*60)" :max="goal*60" aria-label="今日阅读目标"/><small>{{summary.todaySeconds>=goal*60?'今日目标已完成':goal+' 分钟目标'}}</small></article><article class="insights-number"><Flame :size="21"/><strong>{{summary.streak}}<small>天</small></strong><span>连续阅读</span></article><article class="insights-number"><BookOpen :size="21"/><strong>{{summary.books}}<small>本</small></strong><span>留下阅读时间</span></article></div><section class="insights-week"><div class="insights-section-heading"><h2>这一周</h2><span>{{minutes(summary.week.reduce((sum,d)=>sum+d.seconds,0))}} 分钟</span></div><div class="insights-chart" role="list" aria-label="七日阅读时间"><div v-for="day in summary.week" :key="day.date" role="listitem" :aria-label="day.date+' · '+minutes(day.seconds)+' 分钟'"><small>{{minutes(day.seconds)}}</small><div class="insights-track"><span :style="{height:day.seconds?Math.max(3,day.seconds/max*100)+'%':'0'}"/></div><span>{{day.date.slice(5).replace('-','/')}}</span></div></div></section><section class="insights-badges"><div class="insights-section-heading"><h2>慢慢积累</h2><span>累计 {{minutes(summary.seconds)}} 分钟</span></div><div class="insights-badge-grid"><article :class="{earned:summary.badges.first}"><Award :size="27"/><strong>翻开一页</strong><small>阅读 1 分钟</small><span>{{summary.badges.first?'已获得':'未获得'}}</span></article><article :class="{earned:summary.badges.hour}"><Clock3 :size="27"/><strong>故事里的时光</strong><small>累计 60 分钟</small><span>{{summary.badges.hour?'已获得':'未获得'}}</span></article><article :class="{earned:summary.badges.threeDays}"><Flame :size="27"/><strong>每日相遇</strong><small>连续阅读 3 天</small><span>{{summary.badges.threeDays?'已获得':'未获得'}}</span></article></div></section><form class="insights-goal" @submit.prevent="save"><label>每日目标<input aria-label="每日目标" v-model.number="goal" type="number" min="5" max="240" required :disabled="busy">分钟</label><button class="final-primary" :disabled="busy||conflict">保存目标</button><small v-if="saved" role="status">已保存</small></form></template></section></template>
<style scoped>
.private-insights{max-width:1080px}.insights-top{display:grid;grid-template-columns:2fr 1fr 1fr;gap:20px}.insights-top article,.insights-week,.insights-badges,.insights-goal{background:var(--canvas);border:1px solid var(--edge);border-radius:20px;padding:28px}.insights-today>span{display:flex;gap:10px;align-items:center;color:var(--quiet)}.insights-today p{margin:16px 0}.insights-today strong{font:64px serif;margin-right:12px;color:var(--accent)}.insights-today progress{display:block;width:100%;height:6px;accent-color:var(--accent);margin:16px 0}.insights-today small{color:var(--quiet)}.insights-number{display:flex;flex-direction:column;justify-content:center;gap:18px;color:var(--quiet)}.insights-number strong{font:38px serif;color:var(--ink)}.insights-number small{font:13px system-ui;margin-left:8px}.insights-week,.insights-badges{margin-top:24px}.insights-section-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.insights-section-heading h2{font:23px serif;margin:0}.insights-section-heading>span{font-size:13px;color:var(--quiet)}.insights-chart{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:16px;margin-top:30px;text-align:center;font-size:12px;color:var(--quiet)}.insights-chart>div{display:grid;gap:12px}.insights-track{height:140px;position:relative;background:var(--wash);border-radius:8px;overflow:hidden}.insights-track span{position:absolute;bottom:0;left:0;right:0;background:var(--accent);border-radius:8px;transition:height .3s}.insights-badge-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:28px}.insights-badge-grid article{display:grid;justify-items:center;text-align:center;gap:12px;padding:24px 10px;border:1px solid var(--edge);border-radius:16px;color:var(--quiet)}.insights-badge-grid strong{font-size:15px}.insights-badge-grid small,.insights-badge-grid span{font-size:12px}.insights-badge-grid article.earned{color:var(--accent);background:var(--wash);border-color:var(--accent)}.insights-goal{margin-top:24px;display:flex;align-items:center;gap:20px;flex-wrap:wrap}.insights-goal label{display:flex;align-items:center;gap:16px;font-size:14px}.insights-goal input{width:90px;min-height:44px;padding:10px;border:1px solid var(--edge);border-radius:12px;background:var(--canvas);color:var(--ink)}.insights-goal button{min-height:44px}.insights-goal small{color:var(--accent)}
@media(max-width:640px){.insights-top{grid-template-columns:1fr 1fr;gap:12px}.insights-today{grid-column:1/-1}.insights-top article,.insights-week,.insights-badges,.insights-goal{padding:22px}.insights-chart{gap:8px}.insights-badge-grid{gap:8px}.insights-badge-grid article{padding:20px 4px}.insights-badge-grid strong{font-size:13px}.insights-section-heading{flex-wrap:wrap}.insights-number{gap:12px}}
@media(prefers-reduced-motion:reduce){.insights-track span{transition:none}}
</style>
